<script setup>
import {ref,onMounted} from 'vue';import {store,api,cargar} from './store';const listo=ref(false),registro=ref(false),error=ref(''),form=ref({nombre:'',email:'',password:''});const menus=[['/','Inicio'],['/cursos','Cursos'],['/actividades','Actividades'],['/calendario','Calendario'],['/progreso','Progreso']];
onMounted(async()=>{try{store.usuario=await api('/me');await cargar()}catch(e){store.usuario=null}finally{listo.value=true}});
async function entrar(){error.value='';try{store.usuario=await api(registro.value?'/registro':'/login','POST',form.value);await cargar();form.value.password=''}catch(e){store.usuario=null;error.value=e.message}}
async function salir(){try{await api('/logout','POST');store.usuario=null;store.cursos=[];store.tareas=[]}catch(e){error.value=e.message}}
</script>
<template><div v-if="!listo" class="p-5">Cargando...</div><div v-else-if="!store.usuario" class="login"><form class="card p-4 shadow-sm" @submit.prevent="entrar"><h2>StudyPlan</h2><p class="text-secondary">{{registro?'Crea tu cuenta':'Inicia sesión para organizar tus estudios'}}</p><div v-if="error" class="alert alert-danger">{{error}}</div><label v-if="registro" class="mb-3">Nombre<input class="form-control" v-model="form.nombre" required></label><label class="mb-3">Correo<input class="form-control" type="email" v-model="form.email" required></label><label class="mb-3">Contraseña<input class="form-control" type="password" v-model="form.password" minlength="8" required></label><button class="btn btn-primary">{{registro?'Registrarme':'Ingresar'}}</button><button type="button" class="btn btn-link" @click="registro=!registro;error=''">{{registro?'Ya tengo cuenta':'Crear cuenta'}}</button></form></div><div v-else class="layout"><aside><h3>StudyPlan</h3><p class="small text-white-50">Organizador académico</p><nav class="nav flex-column gap-2"><RouterLink v-for="m in menus" :key="m[0]" :to="m[0]" class="nav-link" exact-active-class="active">{{m[1]}}</RouterLink></nav></aside><main class="container-fluid p-3 p-lg-4"><header class="d-flex justify-content-between align-items-center mb-4"><div><small class="text-secondary">MI ESPACIO ACADÉMICO</small><h4>Hola, {{store.usuario.nombre}}</h4></div><button class="btn btn-outline-secondary" @click="salir">Cerrar sesión</button></header><p v-if="error" class="alert alert-danger">{{error}}</p><RouterView/></main></div></template>